        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def nth_polite_number(n):
    count = 0
    num = 1
    while True:
        if is_polite(num):
            count += 1
            if count == n:
                return num
        num += 1
